    "spiced-cookie-butter-latte": { title: "Spiced cookie spread latte", capsule: "Arpeggio", ingredients: ["1 Arpeggio capsule", "2 tbsp spiced cookie spread", "¼ tsp cinnamon, plus more to serve", "A pinch of ground nutmeg", "120–180 ml milk"], steps: ["Add the cookie spread, cinnamon, and nutmeg to a tall glass.", "Heat and froth the milk, pour it into the glass, then stir until smooth.", "Brew an Arpeggio espresso on top and finish with cinnamon."], adaptationNote: "Original-line adaptation: rich Arpeggio replaces Bianco Intenso Professional." },
