export function localizeRecipe(recipe: CoffeeRecipe, locale: Locale): CoffeeRecipe {
  if (locale === "ru") return recipe;
  const text = recipes[locale][recipe.id];
  const minutes = Number.parseInt(recipe.time, 10);
  const time = Number.isNaN(minutes)
    ? recipe.time
    : `${recipe.time.trim().startsWith("<") ? "< " : ""}${minutes} min`;
  const sourceLabel = recipe.sourcePage
    ? locale === "en" ? `Nespresso Recipe Book · p. ${recipe.sourcePage}` : `Livre de recettes Nespresso · p. ${recipe.sourcePage}`
    : locale === "en" ? "Nespresso source" : "Source Nespresso";
  const difficulty = recipe.difficulty === "Средняя"
    ? locale === "en" ? "Medium" : "Moyenne"
    : locale === "en" ? "Easy" : "Facile";
  const imageAlt = recipe.sourcePage
    ? locale === "en" ? `${text.title} — photo from the Nespresso recipe book` : `${text.title} — photo du livre de recettes Nespresso`
    : locale === "en" ? `${text.title} — Nespresso photo` : `${text.title} — photo Nespresso`;
  return {
    ...recipe,
    ...text,
    time,
    difficulty,
    sourceLabel,
    imageAlt,
  };
}
